        return new CustomerResponse(
                customer.getId(),
                customer.getFirstName(),
                customer.getLastName(),
                customer.getEmail(),
                customer.getPhone(),
                customer.getNip());
    }

    // E-mail is unique case-insensitively: the DB unique constraint then enforces it too.
